from datetime import date, timedelta
from calendar import monthrange


def recur(start: str, rule: str, count: int) -> list[str]:
    first = date.fromisoformat(start)
    parts = rule.split()
    kind, k = parts[0], int(parts[1])

    if kind == "DAILY":
        return [
            (first + timedelta(days=i * k)).isoformat()
            for i in range(count)
        ]

    weekdays = {
        "MO": 0, "TU": 1, "WE": 2, "TH": 3,
        "FR": 4, "SA": 5, "SU": 6,
    }
    result = []

    if kind == "WEEKLY":
        days = sorted(weekdays[wd] for wd in parts[2].split(","))
        monday = first - timedelta(days=first.weekday())

        while True:
            for wd in days:
                candidate = monday + timedelta(days=wd)
                if candidate >= first:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result
            monday += timedelta(weeks=k)

    if kind == "MONTHLY":
        month_index = first.year * 12 + first.month - 1

        while True:
            year, month_zero = divmod(month_index, 12)
            month = month_zero + 1
            first_weekday, last_day = monthrange(year, month)

            if len(parts) == 3:
                requested = int(parts[2])
                day = last_day if requested == -1 else requested
            else:
                n = int(parts[2])
                wd = weekdays[parts[3]]
                if n == -1:
                    last_weekday = (first_weekday + last_day - 1) % 7
                    day = last_day - (last_weekday - wd) % 7
                else:
                    day = 1 + (wd - first_weekday) % 7 + 7 * (n - 1)

            if day <= last_day:
                candidate = date(year, month, day)
                if candidate >= first:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result

            month_index += k

    month, day = map(int, parts[2].split("-"))
    year = first.year

    while True:
        if day <= monthrange(year, month)[1]:
            candidate = date(year, month, day)
            if candidate >= first:
                result.append(candidate.isoformat())
                if len(result) == count:
                    return result
        year += k
